import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import fc from 'fast-check';
import { mergeIntervals } from './intervals.mjs';

const pointIntervalsArb = fc
  .array(fc.tuple(fc.integer({ min: -50, max: 50 }), fc.integer({ min: -50, max: 50 })), {
    maxLength: 20,
  })
  // normalize each pair so start <= end
  .map((pairs) =>
    pairs.map(([a, b]) => (a <= b ? [a, b] : [b, a]))
  );

function membershipOracle(intervals, x) {
  // brute-force: is x covered by any input interval? (integer points only)
  for (const [s, e] of intervals) {
    if (x >= s && x <= e) return true;
  }
  return false;
}

describe('mergeIntervals properties', () => {
  test('output is sorted, strictly non-overlapping AND non-touching (gap > 0)', () => {
    fc.assert(
      fc.property(pointIntervalsArb, (intervals) => {
        const merged = mergeIntervals(intervals);
        for (let i = 0; i < merged.length; i++) {
          const [s, e] = merged[i];
          assert.ok(s <= e, `degenerate interval ${merged[i]}`);
          if (i > 0) {
            const prevEnd = merged[i - 1][1];
            assert.ok(
              s > prevEnd,
              `overlap/touch at index ${i}: ${merged[i - 1]} vs ${merged[i]}`
            );
          }
        }
      })
    );
  });

  test('membership preserved: every integer point in inputs is in output', () => {
    fc.assert(
      fc.property(pointIntervalsArb, (intervals) => {
        const merged = mergeIntervals(intervals);
        for (const [s, e] of intervals) {
          for (let x = s; x <= e; x++) {
            assert.ok(
              membershipOracle(merged, x),
              `point ${x} from input [${s},${e}] missing from output`
            );
          }
        }
      })
    );
  });

  test('no spurious coverage: every integer point in output was in inputs', () => {
    fc.assert(
      fc.property(pointIntervalsArb, (intervals) => {
        const merged = mergeIntervals(intervals);
        for (const [s, e] of merged) {
          for (let x = s; x <= e; x++) {
            assert.ok(
              membershipOracle(intervals, x),
              `spurious point ${x} in output interval [${s},${e}]`
            );
          }
        }
      })
    );
  });

  test('regression: touching intervals [1,2] and [2,3] must merge to [1,3]', () => {
    assert.deepEqual(mergeIntervals([[1, 2], [2, 3]]), [[1, 3]]);
    // same class of counterexample, unsorted input order
    assert.deepEqual(mergeIntervals([[2, 3], [1, 2]]), [[1, 3]]);
    // touching chain
    assert.deepEqual(mergeIntervals([[1, 2], [2, 3], [3, 4]]), [[1, 4]]);
    // contained interval
    assert.deepEqual(mergeIntervals([[1, 10], [2, 3]]), [[1, 10]]);
    assert.deepEqual(mergeIntervals([]), []);
  });
});

